import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十八章","description":"《正易心法》第十八章——诸卦名义，须究端的：古今失正的二十二卦，逐对纠正其名义——师比汤武、同人大有舜禹、履小畜臣道、无妄大畜君道、临观出入、谦豫止动、生命四卦、渐归妹、噬嗑贲、丰旅。","frontmatter":{"title":"正易心法·第十八章","description":"《正易心法》第十八章——诸卦名义，须究端的：古今失正的二十二卦，逐对纠正其名义——师比汤武、同人大有舜禹、履小畜臣道、无妄大畜君道、临观出入、谦豫止动、生命四卦、渐归妹、噬嗑贲、丰旅。","category":"guide","aliases":["正易心法第十八章","诸卦名义须究端的","二十二卦名义"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-18.md","filePath":"yijing/zheng-yi-xin-fa/chapter-18.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-18.md"},x=p({...c,setup(u){const i=[{id:"z18-01",label:"一、名义须究端的",showLabel:!0,sentences:[["诸卦名义，须究",{text:"端的",glossary:"duandi"},"。名义不正，《易》道",{text:"悬绝",glossary:"xuanjue"},"。"]],note:["各卦的名称与含义，必须追究到准确无误。名义不正确，《易》道就悬空断绝了。（「悬绝」＝悬空而没有落脚点、断绝而无法贯通。**这就是「落处」的反面**：名义正，则根扎入土；名义不正，则根悬于空。）"]},{id:"z18-02",label:"二、古今失正二十余卦",showLabel:!0,sentences:[["《易》卦名义，古今失其正者，二十余卦：师、比、小畜、履、同人、大有、谦、豫、临、观、噬嗑、贲、无妄、大畜、颐、大过、渐、归妹、丰、旅、中孚、小过是也。"]],note:["《易》卦的名义，古今失去正确理解的，有二十余卦：师、比、小畜、履、同人、大有、谦、豫、临、观、噬嗑、贲、无妄、大畜、颐、大过、渐、归妹、丰、旅、中孚、小过。（**恰好是十一对反对卦**——麻衣把它们成对列出，正是第十七章「名义无不反对」的具体验证。）"]},{id:"z18-03",label:"三、创业与嗣位",showLabel:!0,sentences:[["盖师以正众，比以兴王，二卦以武功创业，",{text:"汤武",glossary:"tangwu"},"之卦也。同人穷而在下，大有达而在上，二卦以文德嗣位，",{text:"舜禹",glossary:"shunyu"},"之卦也。"]],note:["师以整治众人，比以兴起王业——两卦以武功创业，是商汤、周武王的卦。同人处穷困在下，大有处通达在上——两卦以文德继承帝位，是舜、禹的卦。（**这两个历史原型不是随意比附，而是卦画结构的印证**：师☷☵一阳统众阴＝将帅统兵；比☷☵一阳居众阴之上＝众人归附；同人☰☲离在下＝文明之人处于下位；大有☲☰离在上＝文明之德居于上位。）"]},{id:"z18-04",label:"四、臣道与君道",showLabel:!0,sentences:[["履以阴德而蹈艰危，以致小畜之安富；人臣之事也。无妄以阴德而践",{text:"灾眚",glossary:"zaisheng"},"，以致大畜之喜庆，人君之事也。"]],note:["履以阴柔之德踩踏艰险危难，从而达到小畜的安富——这是人臣的处世之道。无妄以阴柔之德经历灾难祸患，从而达到大畜的喜庆——这是人君的处世之道。（两组的路径相同：**以阴德处难，终得回报**；差别在规模：臣子得「小成」（小畜），君主得「大成」（大畜）。）"]},{id:"z18-05",label:"五、出入与止动",showLabel:!0,sentences:[["临以阳来，宜出而有为；观以阴生，宜入而无为。谦则止在象后而存义，豫则动在象前而",{text:"知几",glossary:"zhiji"},"。"]],note:["临以阳气来临，宜于出外有所作为；观以阴气生长，宜于退入无所作为。谦是止步在卦象之后而保存义理；豫是行动在卦象之前而知晓先机。（临、观都是十二消息卦：**临（二阳在下）宜出，观（二阳在上、阴渐盛）宜入**——知时而动。谦、豫则是一止一动：谦（艮止在下）止而后存义，豫（震动在先）动而先知几。）"]},{id:"z18-06",label:"六、生命与婚配",showLabel:!0,sentences:[["中孚则始生，小过则夭折。颐则成人而养生，大过则寿终而丧死。渐以正而进，归妹以说而合。"]],note:["中孚象征生命开始，小过象征生命夭折；颐象征成人之后的养生，大过象征寿终正寝而死亡。渐以正道循序渐进，归妹以喜悦而结合。（**生命四卦正是第十六章所说的「对体卦」**：中孚（始生）、小过（夭折）、颐（养生）、大过（丧死）——四个生命的关键节点，正是「死生寿夭造化之枢机」的具体内容。渐与归妹则是一正一悦：正式的婚配 vs 悦而结合。）"]},{id:"z18-07",label:"七、德命之别与谛观",showLabel:!0,sentences:[["噬嗑以贪而致罪，贲以义而致饰。丰则得所归而富盛，旅则失所基而困穷。凡此二十余卦，其名义显然，见于卦画反对，有不可掩者如此，当",{text:"谛观",glossary:"diguan"},"之也。《大传》曰：“天下之动，贞夫一者也。”苟名义不当，则一卦无所",{text:"归宿",glossary:"guisu"},"也，故曰：《易》道悬绝也。"]],note:["噬嗑以贪婪而导致罪过，贲以义理而导致文饰；丰是得到归宿而富足盛大，旅是失去根基而困顿穷乏。这二十余卦，其名义显然见于卦画反对，有不可掩盖的道理，应当仔细观察。《大传》说「天下的变动，以正为准则」；如果名义不正确，则一卦就无所归宿了，所以说：《易》道悬绝。（**「归宿」是本章的关键词**——名义正，则每卦有明确的落处；名义不正，则「一卦无所归宿」。这与第一章的「落处」是同一件事，只是换了一个说法。）"]}],o=[{id:"duandi",term:"端的",pinyin:"duān dì",meaning:"确切的、正确的。究端的：追究到准确无误。"},{id:"xuanjue",term:"悬绝",pinyin:"xuán jué",meaning:"悬空断绝。悬＝没有落脚点，绝＝无法贯通。名义不正的后果。"},{id:"tangwu",term:"汤武",pinyin:"tāng wǔ",meaning:"商汤、周武王。以武功创业的历史原型，对应师、比二卦。"},{id:"shunyu",term:"舜禹",pinyin:"shùn yǔ",meaning:"舜、禹。以文德禅让继位的历史原型，对应同人、大有二卦。"},{id:"zaisheng",term:"灾眚",pinyin:"zāi shěng",meaning:"灾难祸患。眚是过失、灾祸。"},{id:"zhiji",term:"知几",pinyin:"zhī jī",meaning:"知晓机兆。几是事物变化的微妙先兆。豫卦动在象前，故能知几。"},{id:"diguan",term:"谛观",pinyin:"dì guān",meaning:"仔细观察。谛是仔细、审慎。"},{id:"guisu",term:"归宿",pinyin:"guī sù",meaning:"最终的归属。名义正，则一卦有归宿；名义不正，则无所归宿。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t("",21)),e(r,{colophon:"须究端的 · 二十二卦 · 汤武舜禹 · 名义归宿",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十八章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"须究端的",pinyin:["jiū","duān"],meaning:"卦名与含义必须追究到准确无误——名义不正确，《易》道就悬空断绝。"},{term:"汤武之卦",pinyin:["tāng","wǔ"],meaning:"师（正众）与比（兴王）以武功创业，是商汤、周武王的卦。卦画：师＝一阳统众阴，比＝一阳居众阴上。"},{term:"舜禹之卦",pinyin:["shùn","yǔ"],meaning:"同人（穷而在下）与大有（达而在上）以文德嗣位，是舜、禹的卦。"},{term:"臣道 · 君道",pinyin:["chén","dào"],meaning:"履→小畜（阴德蹈艰致安富）为臣道；无妄→大畜（阴德践灾致喜庆）为君道。规模不同，路径相同。"},{term:"生命四卦",pinyin:["shēng","mìng"],meaning:"中孚（始生）、小过（夭折）、颐（养生）、大过（丧死）——四卦皆为对体卦，正是「死生寿夭造化之枢机」。"},{term:"归宿",pinyin:["guī","sù"],meaning:"名义正，则一卦有明确的落处（归宿）；名义不当，则一卦无所归宿，故曰「《易》道悬绝」。"}]}),n[3]||(n[3]=t("",26))])}}});export{y as __pageData,x as default};
